  async function refreshProviderStatus(){setConnectionError("");try{const status=await api("/api/provider-status");setProviderStatus(status);setBackendHealthy(true);if(!initialProviderSelectionRef.current){initialProviderSelectionRef.current=true;setProviderMode(visibleProviderMode(providerCatalog,status,providerMode,explicitProviderChoiceRef.current));}}catch(e){setProviderStatus(null);setBackendHealthy(false);setConnectionError(e.message);}}
