  if(LAN_MODE&&!lanAccessCode)return <div className="engine-launcher"><section className="launcher-card lan-access"><div className="launcher-brand"><div className="launcher-logo"><img src="./cureflow-logo.png" alt="CureFlow"/></div><b>CureFlow 局域网访问</b></div><p>请输入运行服务的电脑在终端显示的本次访问码。访问码只保存在当前浏览器标签页；请勿在公共网络使用。</p><form onSubmit={unlockLan}><label htmlFor="lan-access-code">本次访问码</label><input id="lan-access-code" type="password" value={lanEntry} onChange={event=>setLanEntry(event.target.value)} autoComplete="off" spellCheck="false"/><button type="submit">进入 CureFlow</button></form>{lanError&&<p role="alert" className="error">{lanError}</p>}</section></div>;
